fn replace_once(source:&mut String,from:&str,to:&str,label:&str){
    let count=source.matches(from).count();
    assert_eq!(count,1,"v1.18.0 patch {label} expected one match, found {count}");
    *source=source.replacen(from,to,1);
}
fn replace_between(source:&mut String,start:&str,end:&str,replacement:&str,label:&str){
    let count=source.matches(start).count();
    assert_eq!(count,1,"v1.18.0 patch {label} start expected one match, found {count}");
    let begin=source.find(start).expect("v1.18.0 start anchor");
    let rel_end=source[begin..].find(end).unwrap_or_else(||panic!("v1.18.0 patch {label} end anchor missing"));
    source.replace_range(begin..begin+rel_end,replacement);
}

